import { KDSOrder } from '../types/kds';
import { generateSeedOrders } from '../utils/orderSeedGenerator';
import { useKDSStore } from '../store/kdsStore';
import { useKDSAccessStore } from '../store/kdsAccessStore';
import { useSoundStore } from '../store/useSoundStore';
import { useFilterStore } from '../store/useFilterStore';
import { configureDispatcher } from './kdsEventDispatcher';

export interface KDSBootstrapData {
    user: {
        user_id: string;
        role_id: string;
        brand_id: string;
        store_id: string;
        permissions: string[];
    };
    station: {
        station_id: string;
        station_name: string;
        type: string;
    };
    routing_rules: Record<string, any>;
    sound_config: Record<string, any>;
    orders: KDSOrder[];
}

/**
 * Mock KDS bootstrap function.
 * Simulates a backend response with seed data.
 */
export async function mockKDSBootstrap(): Promise<KDSBootstrapData> {
    // Simulate network latency (will be replaced with real GET /api/kds/bootstrap)
    await new Promise(resolve => setTimeout(resolve, 300));

    const mockOrders = generateSeedOrders();

    return {
        user: {
            user_id: "mock-user-1",
            role_id: "STORE_MANAGER",
            brand_id: "brand-demo",
            store_id: "store-demo",
            permissions: [
                "KDS.VIEW",
                "KDS.STAGE_UPDATE",
                "KDS.ACCEPT_ORDER",
                "KDS.PRINT",
                "KDS.REASSIGN_STATION",
                "KDS.RECALL_REFIRE",
                "KDS.DELAY_ORDER",
                "KDS.CANCEL_ORDER",
                "KDS.CUSTOMER_MESSAGE"
            ]
        },
        station: {
            station_id: "kitchen-main",
            station_name: "Kitchen",
            type: "KITCHEN"
        },
        routing_rules: {},
        sound_config: {},
        orders: mockOrders
    };
}

/**
 * Main bootstrap entry point.
 * Hydrates all KDS-related stores with the bootstrap data.
 */
export async function bootstrapKDS() {
    const data = await mockKDSBootstrap();

    // 1. Hydrate Access Store
    const accessStore = useKDSAccessStore.getState();
    accessStore.setUserContext({
        userId: data.user.user_id,
        roleId: data.user.role_id,
        brandId: data.user.brand_id,
        storeId: data.user.store_id,
        permissions: data.user.permissions,
    });

    accessStore.setStationContext({
        stationId: data.station.station_id,
        isStationMode: true,
    });

    // 2. Hydrate KDS Store (Orders + Routing Rules)
    const kdsStore = useKDSStore.getState();
    if (data.orders.length > 0) {
        kdsStore.batchUpdateOrders(data.orders);
    }
    if (Object.keys(data.routing_rules).length > 0) {
        kdsStore.setRoutingRules(data.routing_rules);
    }

    // 3. Hydrate Sound Store
    const soundStore = useSoundStore.getState();
    if (Object.keys(data.sound_config).length > 0) {
        soundStore.setSettings({
            volume: data.sound_config.volume ?? 0.5,
            newOrder: data.sound_config.newOrder ?? true,
            delayed: data.sound_config.delayed ?? true,
            overdue: data.sound_config.overdue ?? true,
        });
    }

    // 4. Reset Filter Store (Initial clean state for new session)
    useFilterStore.getState().resetFilters();

    // 5. Configure Event Dispatcher
    configureDispatcher({
        tenantId: data.user.brand_id,
        storeId: data.user.store_id,
    });

    console.info(`[KDSBootstrap] Mock bootstrap complete for ${data.user.user_id}`);
    return data;
}
